/* Publish configuration only after exact vehicle/year/trim evidence is verified. */
const VEHICLE_CONFIGS=Object.fromEntries(['718','x5','my','e','gl8','magotan','passat','jetta','coaster','h7','gl8-653','denza-d9'].map(id=>[id,{
 verified:false,year:null,trim:null,seats:null,bags:null,drive:null,energy:null,transmission:null,carplay:null,features:[],source:null,verifiedAt:null
}]));
VEHICLE_CONFIGS.passat.year=2014;
VEHICLE_CONFIGS.h7.reportedYear=2022;
VEHICLE_CONFIGS.gl8.series='陆尊';
VEHICLE_CONFIGS['gl8-653'].reportedDesignation='653T';
VEHICLE_CONFIGS['gl8-653'].reportedColor='棕色';
VEHICLE_CONFIGS['gl8-653'].reportedSeries='陆尊';
VEHICLE_CONFIGS['gl8-653'].seriesVerified=false;
VEHICLE_CONFIGS['gl8-653'].modelingReference={year:2022,series:'ES陆尊 653T',testVariants:['舒适型','豪华型','旗舰型'],sourceUrl:'https://www.ciasi.org.cn/uploads/files/e6f45547c9d28d06d333719f56e5acd1.pdf'};
function modelingReferenceHTML(car){const reference=configFor(car).modelingReference;if(!reference)return '';return `<section class="modeling-reference"><h3>2022 年款建模参考资料</h3><p>官方测评资料列出 ES陆尊 653T 舒适型、豪华型和旗舰型，具体实车版本仍待核实。</p><a href="${reference.sourceUrl}" target="_blank" rel="noopener noreferrer">查看 C-IASI 官方测试报告 ↗</a><p class="configuration-note">公开车型资料用于年款与版本核对，不能证明租赁实车的配置或改装情况。</p></section>`}

function configFor(car){const base=Object.assign({verified:false},VEHICLE_CONFIGS[car.id]||{});const fact=VEHICLE_FACTS[car.id];if(!fact)return base;const out=Object.assign({},base);for(const k of Object.keys(fact)){const v=fact[k];if(v!==null&&v!==undefined)out[k]=v}if(fact.confirmed===true)out.verified=true;return out}
function carSeats(car){const v=configFor(car).seats;return v==null?null:v}
function carBags(car){const v=configFor(car).bags;return v==null?null:v}
function meetsSeatCriterion(car,minimum){const seats=carSeats(car);if(seats!=null)return seats>=minimum;if(minimum===7)return /MPV|中巴/.test(car.type);if(minimum===5)return /轿车|SUV|MPV|中巴/.test(car.type);return false}
function configValue(car,key){const value=configFor(car)[key];return value===null||value===undefined?'待确认':value}
function capacityLabel(car,key,unit){const value=configFor(car)[key];return value===null||value===undefined?'待确认':value+' '+unit}
function carSpecs(car){return `<span>座位：${capacityLabel(car,'seats','座')}</span><span>变速箱：${configValue(car,'transmission')}</span><span>驱动：${configValue(car,'drive')}</span><span>配置待核实</span>`}
function yuan(n){return '¥'+Math.round(n).toLocaleString('zh-CN')}
function vehicleFactsHTML(car){
 const f=VEHICLE_FACTS[car.id]||{},en=state.lang==='en',pending=en?'To be confirmed':'待确认';
 const rows=[[en?'Model year':'年款',f.year],[en?'Trim':'具体版本',f.trim],[en?'Seats':'核定座位',f.seats==null?null:f.seats+' 座'],[en?'Luggage (24")':'行李件数（24寸）',f.bags==null?null:f.bags+' 件'],[en?'Drive':'驱动形式',f.drive],[en?'Energy':'能源类型',f.energy],[en?'Transmission':'变速箱',f.transmission],[en?'Apple CarPlay':'Apple CarPlay',f.carplay==null?null:(f.carplay?en?'Confirmed':'已确认配备':en?'Not fitted':'已确认未配备')],[en?'Daily rate':'日租价',f.price==null?null:yuan(f.price)+' / 天'+(f.confirmed?'':'（演示参考）')],[en?'Deposit':'租车押金',f.deposit==null?null:yuan(f.deposit)]];
 return `<section class="vehicle-facts"><h3>${en?((f.confirmed?'Confirmed data · ':'Data pending verification · ')+car.en):((f.confirmed?'这台车的已核对资料 · ':'这台车的待核对资料 · ')+car.name)}</h3><dl class="configuration-list">${rows.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd class="${v==null?'pending':''}">${v==null?esc(pending):esc(v)}</dd></div>`).join('')}</dl>${f.note?`<p class="configuration-note">${esc(f.note)}</p>`:''}</section>`;
}
function rentalTermsHTML(){
 const t=RENTAL_TERMS,en=state.lang==='en';
 const rows=[[en?'Minimum rental':'最短租期',t.minRentalDays==null?null:t.minRentalDays+' 天'],[en?'Minimum driver age':'驾驶员最小年龄',t.minDriverAge],[en?'Licence held for':'驾照最短持证年限',t.minLicenceYears==null?null:t.minLicenceYears+' 年'],[en?'Free distance':'每日免费里程',t.freeKmPerDay==null?null:t.freeKmPerDay+' km'],[en?'Extra distance':'超公里单价',t.excessKmPrice==null?null:yuan(t.excessKmPrice)+' / km'],[en?'Overtime':'超时单价',t.overtimeHourPrice==null?null:yuan(t.overtimeHourPrice)+' / 小时'],[en?'Free cancellation':'免费取消时限',t.cancelFreeHours==null?null:'出发前 '+t.cancelFreeHours+' 小时'],[en?'Fuel policy':'油电政策',t.fuelPolicy],[en?'Tolls and parking':'路桥与停车费',t.tollParkingPolicy],[en?'Driver meals/accommodation':'司机餐宿',t.driverMealAccommodation],[en?'Insurance excess':'事故自负额',t.insuranceExcess==null?null:yuan(t.insuranceExcess)]];
 const filled=rows.filter(([,v])=>v!=null);
 if(!filled.length)return `<section class="vehicle-facts"><h3>${en?'Rental terms':'租车与合同条款'}</h3><p class="configuration-note">${en?'Terms are confirmed per booking and listed before you pay.':'合同条款在每次预订前逐项确认并列明，预订前不会自动扣款。'}</p></section>`;
 return `<section class="vehicle-facts"><h3>${en?'Rental terms':'租车与合同条款'}</h3><dl class="configuration-list">${filled.map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>${t.contractUrl?`<p class="configuration-source"><a href="${esc(t.contractUrl)}" target="_blank" rel="noopener noreferrer">${en?'Contract template':'查看合同模板'} ↗</a></p>`:''}</section>`;
}
function configurationHTML(car){const r=VEHICLE_OFFICIAL_REFERENCES[car.id];const facts=vehicleFactsHTML(car)+rentalTermsHTML();if(!r)return facts;if(state.lang==='en')return facts+`<p class="configuration-note">Official model references. Match the year and trim to the actual rental vehicle.</p><dl class="configuration-list">${VEHICLE_REFERENCE_EN[car.id].map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><p><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">Official source ↗</a> · Researched: 2026-10-13</p><p class="configuration-note">Bag capacity, CarPlay and parking cameras require a vehicle check.</p>`;return facts+`<p class="configuration-note">${esc(r.scope)}。以下为公开车型参考，租赁实车年份与版本仍需核对。</p><dl class="configuration-list">${r.rows.map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl><p class="configuration-source"><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">查看官方配置 / 车型资料 ↗</a> · 检索：2026-10-13</p><p class="configuration-note">行李承载、CarPlay 与泊车影像按实车核对。</p>`;}
function vehiclePhoto(car,attributes=''){return car.image?`<img src="${esc(webImage(car.image))}" ${attributes} onerror="this.onerror=null;const p=document.createElement('div');p.className='vehicle-photo-pending';p.setAttribute('role','img');p.setAttribute('aria-label','车型图片暂时无法加载');p.textContent='车型图片暂时无法加载';this.replaceWith(p)"/>`:'<div class="vehicle-photo-pending" role="img" aria-label="等待实车照片">等待实车照片</div>'}

